import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_07_sarsa_quintuple.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_07_sarsa_target.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_07_on_policy_loop.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_07_cliff_walking.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_07_sarsa_qlearning.png",S=JSON.parse('{"title":"为什么 Sarsa 会绕开悬崖？同策略学习真正“同”在哪里","description":"时序差分学习解决了“不等到终点也能更新价值”的问题，但仅有状态价值 \\\\(V(s)\\\\) 还不能在未知模型下直接比较动作。Sarsa 把学习对象换成动作价值 \\\\(Q(s,a)\\\\)，并把智能体实际选择的下一动作写进更新目标，于是价值预测、探索和策略改进组成了一个可以逐步运行的控制闭环。","frontmatter":{"title":"为什么 Sarsa 会绕开悬崖？同策略学习真正“同”在哪里","description":"时序差分学习解决了“不等到终点也能更新价值”的问题，但仅有状态价值 \\\\(V(s)\\\\) 还不能在未知模型下直接比较动作。Sarsa 把学习对象换成动作价值 \\\\(Q(s,a)\\\\)，并把智能体实际选择的下一动作写进更新目标，于是价值预测、探索和策略改进组成了一个可以逐步运行的控制闭环。","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":17,"source":"2026-08-13/rl_series_07_sarsa.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_07_sarsa_quintuple.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-07-sarsa"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"为什么 Sarsa 会绕开悬崖？同策略学习真正“同”在哪里"}],["meta",{"property":"og:description","content":"时序差分学习解决了“不等到终点也能更新价值”的问题，但仅有状态价值 \\\\(V(s)\\\\) 还不能在未知模型下直接比较动作。Sarsa 把学习对象换成动作价值 \\\\(Q(s,a)\\\\)，并把智能体实际选择的下一动作写进更新目标，于是价值预测、探索和策略改进组成了一个可以逐步运行的控制闭环。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-07-sarsa"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_07_sarsa_quintuple.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"为什么 Sarsa 会绕开悬崖？同策略学习真正“同”在哪里"}],["meta",{"name":"twitter:description","content":"时序差分学习解决了“不等到终点也能更新价值”的问题，但仅有状态价值 \\\\(V(s)\\\\) 还不能在未知模型下直接比较动作。Sarsa 把学习对象换成动作价值 \\\\(Q(s,a)\\\\)，并把智能体实际选择的下一动作写进更新目标，于是价值预测、探索和策略改进组成了一个可以逐步运行的控制闭环。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_07_sarsa_quintuple.png"}]],"prev":{"text":"不用等到终点就能学习：时序差分为什么是强化学习的转折点","link":"/rl/rl-series-06-temporal-difference"},"next":{"text":"行为在探索，目标却贪心：Q-learning 为什么能“边走边学最优”","link":"/rl/rl-series-08-q-learning"}},"headers":[],"relativePath":"rl/rl-series-07-sarsa.md","filePath":"rl/rl-series-07-sarsa.md","lastUpdated":null}'),d={name:"rl/rl-series-07-sarsa.md"};function c(_,a,p,u,q,b){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="为什么-sarsa-会绕开悬崖-同策略学习真正-同-在哪里" tabindex="-1">为什么 Sarsa 会绕开悬崖？同策略学习真正“同”在哪里 <a class="header-anchor" href="#为什么-sarsa-会绕开悬崖-同策略学习真正-同-在哪里" aria-label="Permalink to &quot;为什么 Sarsa 会绕开悬崖？同策略学习真正“同”在哪里&quot;">​</a></h1><p>时序差分学习解决了“不等到终点也能更新价值”的问题，但仅有状态价值 (V(s)) 还不能在未知模型下直接比较动作。Sarsa 把学习对象换成动作价值 (Q(s,a))，并把智能体实际选择的下一动作写进更新目标，于是价值预测、探索和策略改进组成了一个可以逐步运行的控制闭环。</p><p>Sarsa 最值得理解的不是名字，而是它对“未来会怎样行动”做出的承诺：训练数据由当前策略产生，更新目标也按当前策略真正选出的下一动作计算。若当前策略保留探索概率，那么探索可能造成的损失也属于该策略的价值，而不是在学习时被假装不存在。</p><p>这正是 Sarsa 与 Q-learning（Q 学习）的分界。前者学习“我按现在这套带探索的行为继续走，结果如何”；后者的一步目标学习“到达下一状态后，如果总选当前价值最大的动作，结果如何”。两者都可以用 <code>ε</code>-贪心采集数据，但更新目标中的下一项不同，学习对象也不同。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-sarsa-是同策略时序差分控制" tabindex="-1">1.1 Sarsa 是同策略时序差分控制 <a class="header-anchor" href="#_1-1-sarsa-是同策略时序差分控制" aria-label="Permalink to &quot;1.1 Sarsa 是同策略时序差分控制&quot;">​</a></h3><p>Sarsa（State–Action–Reward–State–Action，状态—动作—奖励—状态—动作）用五元组 ((S_t,A_t,R_{t+1},S_{t+1},A_{t+1})) 完成一次更新。当前动作和下一动作都由正在执行的策略选出，因此它在采样、评估和改进同一套策略。</p><h3 id="_1-2-同策略不等于策略永远不变" tabindex="-1">1.2 同策略不等于策略永远不变 <a class="header-anchor" href="#_1-2-同策略不等于策略永远不变" aria-label="Permalink to &quot;1.2 同策略不等于策略永远不变&quot;">​</a></h3><p>训练期间，(Q) 持续更新，由 (Q) 派生的 <code>ε</code>-贪心策略也持续变化。“同”指每次数据采集与更新目标对当前行为策略保持一致，不是说从训练开始到结束只允许一个固定策略。</p><h3 id="_1-3-探索风险会进入动作价值" tabindex="-1">1.3 探索风险会进入动作价值 <a class="header-anchor" href="#_1-3-探索风险会进入动作价值" aria-label="Permalink to &quot;1.3 探索风险会进入动作价值&quot;">​</a></h3><p>当下一动作 (A_{t+1}) 偶尔由探索选中时，Sarsa 就使用该动作的 (Q(S_{t+1},A_{t+1})) 构造目标。只要探索在执行中真实存在，它可能带来的后果就属于正在评估的策略。</p><h3 id="_1-4-更谨慎-是有条件的实验现象" tabindex="-1">1.4 “更谨慎”是有条件的实验现象 <a class="header-anchor" href="#_1-4-更谨慎-是有条件的实验现象" aria-label="Permalink to &quot;1.4 “更谨慎”是有条件的实验现象&quot;">​</a></h3><p>在经典悬崖行走任务中，固定探索率下的 Sarsa 往往学到远离悬崖的路线，因为靠近悬崖时一次随机动作可能产生巨大惩罚。但若探索率逐渐降为零，或者奖励、动力学和状态表示改变，这个结论也会改变。不能把单个教材例子升级成普遍安全保证。</p><p><img src="'+o+'" alt="Sarsa 使用实际五元组完成一次同策略更新"></p><h2 id="二、为什么控制必须学习动作价值" tabindex="-1">二、为什么控制必须学习动作价值 <a class="header-anchor" href="#二、为什么控制必须学习动作价值" aria-label="Permalink to &quot;二、为什么控制必须学习动作价值&quot;">​</a></h2><h3 id="_2-1-状态价值只评价-身处这里" tabindex="-1">2.1 状态价值只评价“身处这里” <a class="header-anchor" href="#_2-1-状态价值只评价-身处这里" aria-label="Permalink to &quot;2.1 状态价值只评价“身处这里”&quot;">​</a></h3><p>(V_\\pi(s)) 表示从状态 (s) 开始继续执行策略 (\\pi) 的期望回报。它能告诉我们状态好不好，却没有直接拆开同一状态下各动作的价值。</p><h3 id="_2-2-未知模型时无法用状态价值做一步前瞻" tabindex="-1">2.2 未知模型时无法用状态价值做一步前瞻 <a class="header-anchor" href="#_2-2-未知模型时无法用状态价值做一步前瞻" aria-label="Permalink to &quot;2.2 未知模型时无法用状态价值做一步前瞻&quot;">​</a></h3><p>动态规划拥有转移模型，可以计算动作会把状态带向哪里，再用后继状态价值比较动作。免模型控制没有这张概率表，仅靠 (V(s)) 无法计算每个动作的结果。</p><h3 id="_2-3-动作价值直接回答-在这里这样做" tabindex="-1">2.3 动作价值直接回答“在这里这样做” <a class="header-anchor" href="#_2-3-动作价值直接回答-在这里这样做" aria-label="Permalink to &quot;2.3 动作价值直接回答“在这里这样做”&quot;">​</a></h3><p>动作价值定义为：</p><p>$$ q_\\pi(s,a)=\\mathbb{E}_\\pi[G_t\\mid S_t=s,A_t=a] $$</p><p>它把当前动作固定为 (a)，后续继续遵循策略 (\\pi)。有了 (Q(s,a)) 的估计，智能体无需环境模型，就能在当前状态比较可选动作。</p><h2 id="三、sarsa-的名字就是它的数据流" tabindex="-1">三、Sarsa 的名字就是它的数据流 <a class="header-anchor" href="#三、sarsa-的名字就是它的数据流" aria-label="Permalink to &quot;三、Sarsa 的名字就是它的数据流&quot;">​</a></h2><h3 id="_3-1-从当前状态选择当前动作" tabindex="-1">3.1 从当前状态选择当前动作 <a class="header-anchor" href="#_3-1-从当前状态选择当前动作" aria-label="Permalink to &quot;3.1 从当前状态选择当前动作&quot;">​</a></h3><p>智能体观察 (S_t)，依据当前策略选择 (A_t)。若策略是 <code>ε</code>-贪心，大部分时候选择当前最高价值动作，小部分时候探索其他动作。</p><h3 id="_3-2-环境返回奖励和下一状态" tabindex="-1">3.2 环境返回奖励和下一状态 <a class="header-anchor" href="#_3-2-环境返回奖励和下一状态" aria-label="Permalink to &quot;3.2 环境返回奖励和下一状态&quot;">​</a></h3><p>执行 (A_t) 后，环境产生 (R_{t+1}) 与 (S_{t+1})。到这里已经得到 <code>S-A-R-S</code>，但 Sarsa 还不能完成非终止转移的目标计算。</p><h3 id="_3-3-在下一状态先选出实际下一动作" tabindex="-1">3.3 在下一状态先选出实际下一动作 <a class="header-anchor" href="#_3-3-在下一状态先选出实际下一动作" aria-label="Permalink to &quot;3.3 在下一状态先选出实际下一动作&quot;">​</a></h3><p>智能体必须再次使用当前行为策略，从 (S_{t+1}) 选择 (A_{t+1})。这个动作不是只为公式临时查询，它会在下一次交互中真正执行。由此得到完整的 <code>S-A-R-S-A</code>。</p><h3 id="_3-4-更新后沿用已经选好的动作" tabindex="-1">3.4 更新后沿用已经选好的动作 <a class="header-anchor" href="#_3-4-更新后沿用已经选好的动作" aria-label="Permalink to &quot;3.4 更新后沿用已经选好的动作&quot;">​</a></h3><p>完成 (Q(S_t,A_t)) 更新后，将 (S_{t+1}) 和 (A_{t+1}) 变成新的当前状态与当前动作。实现时若更新后又重新采样一次动作，就可能让目标中的动作与真正执行的动作不一致，破坏同策略数据语义。</p><h2 id="四、把-sarsa-公式逐项拆开" tabindex="-1">四、把 Sarsa 公式逐项拆开 <a class="header-anchor" href="#四、把-sarsa-公式逐项拆开" aria-label="Permalink to &quot;四、把 Sarsa 公式逐项拆开&quot;">​</a></h2><h3 id="_4-1-完整更新公式" tabindex="-1">4.1 完整更新公式 <a class="header-anchor" href="#_4-1-完整更新公式" aria-label="Permalink to &quot;4.1 完整更新公式&quot;">​</a></h3><p>一步 Sarsa 的更新为：</p><p>$$ Q(S_t,A_t)\\leftarrow Q(S_t,A_t)+\\alpha\\left[R_{t+1}+\\gamma Q(S_{t+1},A_{t+1})-Q(S_t,A_t)\\right] $$</p><h3 id="_4-2-sarsa-目标" tabindex="-1">4.2 Sarsa 目标 <a class="header-anchor" href="#_4-2-sarsa-目标" aria-label="Permalink to &quot;4.2 Sarsa 目标&quot;">​</a></h3><p>学习目标是：</p><p>$$ Y_t^{Sarsa}=R_{t+1}+\\gamma Q(S_{t+1},A_{t+1}) $$</p><p>即时奖励来自真实转移，下一动作价值来自当前估计。只需观察一步并选出下一动作，就能形成目标。</p><h3 id="_4-3-sarsa-误差" tabindex="-1">4.3 Sarsa 误差 <a class="header-anchor" href="#_4-3-sarsa-误差" aria-label="Permalink to &quot;4.3 Sarsa 误差&quot;">​</a></h3><p>动作价值的时序差分误差是：</p><p>$$ \\delta_t^{Sarsa}=R_{t+1}+\\gamma Q(S_{t+1},A_{t+1})-Q(S_t,A_t) $$</p><p>它衡量新的一步证据与原动作价值预测是否一致。学习率 (\\alpha) 决定把多少误差写回 (Q(S_t,A_t))。</p><h3 id="_4-4-终止状态要单独处理" tabindex="-1">4.4 终止状态要单独处理 <a class="header-anchor" href="#_4-4-终止状态要单独处理" aria-label="Permalink to &quot;4.4 终止状态要单独处理&quot;">​</a></h3><p>若 (S_{t+1}) 是自然终止状态，后续不再选动作，通常定义后继动作价值为零，此时目标只剩 (R_{t+1})。时间上限截断是否清零，仍应按照任务是否真正结束判断。</p><p><img src="'+l+'" alt="Sarsa 目标由即时奖励和实际下一动作价值组成"></p><h2 id="五、同策略中的-同-究竟指什么" tabindex="-1">五、同策略中的“同”究竟指什么 <a class="header-anchor" href="#五、同策略中的-同-究竟指什么" aria-label="Permalink to &quot;五、同策略中的“同”究竟指什么&quot;">​</a></h2><h3 id="_5-1-行为策略负责生成数据" tabindex="-1">5.1 行为策略负责生成数据 <a class="header-anchor" href="#_5-1-行为策略负责生成数据" aria-label="Permalink to &quot;5.1 行为策略负责生成数据&quot;">​</a></h3><p>行为策略（Behavior Policy，行为策略）决定智能体在环境里实际采取什么动作。状态访问分布、奖励样本和风险暴露都由它产生。</p><h3 id="_5-2-目标策略代表正在学习的行为" tabindex="-1">5.2 目标策略代表正在学习的行为 <a class="header-anchor" href="#_5-2-目标策略代表正在学习的行为" aria-label="Permalink to &quot;5.2 目标策略代表正在学习的行为&quot;">​</a></h3><p>目标策略（Target Policy，目标策略）是价值函数希望评估或优化的策略。Sarsa 中，目标策略就是当前行为策略，因此不需要用重要性采样修正两套策略的分布差异。</p><h3 id="_5-3-策略可以一边评估一边改进" tabindex="-1">5.3 策略可以一边评估一边改进 <a class="header-anchor" href="#_5-3-策略可以一边评估一边改进" aria-label="Permalink to &quot;5.3 策略可以一边评估一边改进&quot;">​</a></h3><p>每次更新 (Q) 后，<code>ε</code>-贪心策略随之改变。Sarsa 一边近似评估当前策略，一边让策略朝更高动作价值方向改进，这属于广义策略迭代（Generalized Policy Iteration，广义策略迭代）。评估不必完全收敛，改进也不必一次完成。</p><h3 id="_5-4-同策略不等于纯贪心" tabindex="-1">5.4 同策略不等于纯贪心 <a class="header-anchor" href="#_5-4-同策略不等于纯贪心" aria-label="Permalink to &quot;5.4 同策略不等于纯贪心&quot;">​</a></h3><p>只要行为策略含探索，Sarsa 学到的就是这套含探索行为的动作价值。若 <code>ε</code> 固定大于零，学习对象长期保留随机动作；若 <code>ε</code> 逐渐趋近零，目标策略也逐渐趋向贪心。</p><p><img src="'+s+'" alt="行为策略既产生数据，也定义 Sarsa 正在评估的策略"></p><h2 id="六、ε-贪心怎样同时处理利用和探索" tabindex="-1">六、<code>ε</code>-贪心怎样同时处理利用和探索 <a class="header-anchor" href="#六、ε-贪心怎样同时处理利用和探索" aria-label="Permalink to &quot;六、`ε`-贪心怎样同时处理利用和探索&quot;">​</a></h2><h3 id="_6-1-大部分概率利用当前知识" tabindex="-1">6.1 大部分概率利用当前知识 <a class="header-anchor" href="#_6-1-大部分概率利用当前知识" aria-label="Permalink to &quot;6.1 大部分概率利用当前知识&quot;">​</a></h3><p>在状态 (s) 下，策略通常选择 (\\arg\\max_a Q(s,a))。这利用了当前动作价值表中最好的已知选择。</p><h3 id="_6-2-小部分概率尝试其他动作" tabindex="-1">6.2 小部分概率尝试其他动作 <a class="header-anchor" href="#_6-2-小部分概率尝试其他动作" aria-label="Permalink to &quot;6.2 小部分概率尝试其他动作&quot;">​</a></h3><p>以概率 <code>ε</code> 在动作集合中随机选择，使尚未充分访问的动作仍有机会获得数据。常见定义让每个动作至少拥有 (\\varepsilon/|\\mathcal A(s)|) 的选择概率。</p><h3 id="_6-3-并列最大动作需要明确打破方式" tabindex="-1">6.3 并列最大动作需要明确打破方式 <a class="header-anchor" href="#_6-3-并列最大动作需要明确打破方式" aria-label="Permalink to &quot;6.3 并列最大动作需要明确打破方式&quot;">​</a></h3><p>若多个动作拥有相同最大价值，只固定选择数组中的首个动作会制造隐含偏好。更合理的教学实现是在并列最大动作中随机选择，并用固定随机种子保证实验可复现。</p><h3 id="_6-4-探索率调度改变学习对象" tabindex="-1">6.4 探索率调度改变学习对象 <a class="header-anchor" href="#_6-4-探索率调度改变学习对象" aria-label="Permalink to &quot;6.4 探索率调度改变学习对象&quot;">​</a></h3><p>固定 <code>ε</code> 关注带持续探索策略的在线表现；逐渐减小 <code>ε</code> 则希望早期充分探索、后期接近贪心。调度方式属于算法定义的一部分，比较实验不能只报告最终 <code>ε</code> 而忽略整个变化过程。</p><h2 id="七、一次-sarsa-交互为什么要先选下一动作" tabindex="-1">七、一次 Sarsa 交互为什么要先选下一动作 <a class="header-anchor" href="#七、一次-sarsa-交互为什么要先选下一动作" aria-label="Permalink to &quot;七、一次 Sarsa 交互为什么要先选下一动作&quot;">​</a></h2><h3 id="_7-1-目标依赖真实将执行的动作" tabindex="-1">7.1 目标依赖真实将执行的动作 <a class="header-anchor" href="#_7-1-目标依赖真实将执行的动作" aria-label="Permalink to &quot;7.1 目标依赖真实将执行的动作&quot;">​</a></h3><p>没有 (A_{t+1})，就无法计算 (Q(S_{t+1},A_{t+1}))。因此 Sarsa 的循环顺序是先执行当前动作、观察转移、选择下一动作，再更新当前动作价值。</p><h3 id="_7-2-下一动作必须被真正复用" tabindex="-1">7.2 下一动作必须被真正复用 <a class="header-anchor" href="#_7-2-下一动作必须被真正复用" aria-label="Permalink to &quot;7.2 下一动作必须被真正复用&quot;">​</a></h3><p>若目标使用一次采样得到的 (A_{t+1})，进入下一步时却重新采样另一个动作，更新所评估的后续行为与数据实际行为发生偏离。即使两次都来自同一概率分布，单条转移的五元组也已经不一致。</p><h3 id="_7-3-终止转移不需要虚构下一动作" tabindex="-1">7.3 终止转移不需要虚构下一动作 <a class="header-anchor" href="#_7-3-终止转移不需要虚构下一动作" aria-label="Permalink to &quot;7.3 终止转移不需要虚构下一动作&quot;">​</a></h3><p>到达自然终止状态后，不应再调用动作选择器制造一个无意义的 (A_{t+1})。直接令自举项为零并完成最后更新即可，这也避免访问终止状态不存在的动作表项。</p><h2 id="八、sarsa-控制闭环怎样运行" tabindex="-1">八、Sarsa 控制闭环怎样运行 <a class="header-anchor" href="#八、sarsa-控制闭环怎样运行" aria-label="Permalink to &quot;八、Sarsa 控制闭环怎样运行&quot;">​</a></h2><h3 id="_8-1-初始化动作价值和探索策略" tabindex="-1">8.1 初始化动作价值和探索策略 <a class="header-anchor" href="#_8-1-初始化动作价值和探索策略" aria-label="Permalink to &quot;8.1 初始化动作价值和探索策略&quot;">​</a></h3><p>为非终止状态动作对设置初始 (Q)，选择学习率、折扣因子和探索率。终止状态动作价值定义为零。</p><h3 id="_8-2-按当前策略产生在线经验" tabindex="-1">8.2 按当前策略产生在线经验 <a class="header-anchor" href="#_8-2-按当前策略产生在线经验" aria-label="Permalink to &quot;8.2 按当前策略产生在线经验&quot;">​</a></h3><p>每一步都由当前 <code>ε</code>-贪心策略选择动作。环境返回奖励和下一状态，训练器再根据同一策略选出下一动作。</p><h3 id="_8-3-用五元组更新当前动作价值" tabindex="-1">8.3 用五元组更新当前动作价值 <a class="header-anchor" href="#_8-3-用五元组更新当前动作价值" aria-label="Permalink to &quot;8.3 用五元组更新当前动作价值&quot;">​</a></h3><p>目标使用真实下一动作价值，更新后再推进状态与动作。策略不需要单独保存成一张表，也可以在每次选动作时由最新 (Q) 即时派生。</p><h3 id="_8-4-通过持续探索和逐渐贪心逼近最优" tabindex="-1">8.4 通过持续探索和逐渐贪心逼近最优 <a class="header-anchor" href="#_8-4-通过持续探索和逐渐贪心逼近最优" aria-label="Permalink to &quot;8.4 通过持续探索和逐渐贪心逼近最优&quot;">​</a></h3><p>表格型 Sarsa 的经典收敛直觉要求所有相关状态动作对被持续访问，同时策略在极限中趋于贪心。只降低探索而没有保证覆盖，或者保持大量探索却声称收敛到纯最优策略，都是不完整的表述。</p><h2 id="九、悬崖行走为什么能看出两种学习对象" tabindex="-1">九、悬崖行走为什么能看出两种学习对象 <a class="header-anchor" href="#九、悬崖行走为什么能看出两种学习对象" aria-label="Permalink to &quot;九、悬崖行走为什么能看出两种学习对象&quot;">​</a></h2><h3 id="_9-1-任务把最短路线放在高风险边缘" tabindex="-1">9.1 任务把最短路线放在高风险边缘 <a class="header-anchor" href="#_9-1-任务把最短路线放在高风险边缘" aria-label="Permalink to &quot;9.1 任务把最短路线放在高风险边缘&quot;">​</a></h3><p>智能体从起点走向终点，每走一步受到小惩罚，踏入悬崖受到巨大惩罚并返回起点。紧贴悬崖的路线最短，但执行带探索的策略时，随机动作可能把智能体推入悬崖。</p><h3 id="_9-2-sarsa-把探索后果算进路径价值" tabindex="-1">9.2 Sarsa 把探索后果算进路径价值 <a class="header-anchor" href="#_9-2-sarsa-把探索后果算进路径价值" aria-label="Permalink to &quot;9.2 Sarsa 把探索后果算进路径价值&quot;">​</a></h3><p>靠近悬崖时，(A_{t+1}) 可能是随机探索动作。Sarsa 使用这个实际动作的价值更新前一步，于是“沿边走时未来仍会探索”的风险会进入动作价值。固定探索率下，它往往偏向更长但与悬崖保持距离的路线。</p><h3 id="_9-3-q-learning-的目标假设后续选择贪心动作" tabindex="-1">9.3 Q-learning 的目标假设后续选择贪心动作 <a class="header-anchor" href="#_9-3-q-learning-的目标假设后续选择贪心动作" aria-label="Permalink to &quot;9.3 Q-learning 的目标假设后续选择贪心动作&quot;">​</a></h3><p>Q-learning 目标使用 (\\max_a Q(S_{t+1},a))，即使数据采集仍由 <code>ε</code>-贪心完成，也按照下一状态的贪心后续行为学习。它可能学到贴近悬崖的最短路径，但训练执行中的随机探索仍会造成跌落。</p><h3 id="_9-4-结果依赖探索率是否持续存在" tabindex="-1">9.4 结果依赖探索率是否持续存在 <a class="header-anchor" href="#_9-4-结果依赖探索率是否持续存在" aria-label="Permalink to &quot;9.4 结果依赖探索率是否持续存在&quot;">​</a></h3><p>若 <code>ε</code> 逐渐趋于零，两种方法最终行为可能都接近最短路径。若碰撞惩罚、动作噪声或动力学改变，路线选择也会变化。因此应报告训练时和评估时的策略、探索率与奖励定义。</p><p><img src="'+h+'" alt="固定探索率下 Sarsa 与 Q-learning 在悬崖附近的路线倾向"></p><h2 id="十、sarsa-与-q-learning-只差下一项吗" tabindex="-1">十、Sarsa 与 Q-learning 只差下一项吗 <a class="header-anchor" href="#十、sarsa-与-q-learning-只差下一项吗" aria-label="Permalink to &quot;十、Sarsa 与 Q-learning 只差下一项吗&quot;">​</a></h2><h3 id="_10-1-公式差异集中在自举目标" tabindex="-1">10.1 公式差异集中在自举目标 <a class="header-anchor" href="#_10-1-公式差异集中在自举目标" aria-label="Permalink to &quot;10.1 公式差异集中在自举目标&quot;">​</a></h3><p>Sarsa 使用：</p><p>$$ R_{t+1}+\\gamma Q(S_{t+1},A_{t+1}) $$</p><p>Q-learning 使用：</p><p>$$ R_{t+1}+\\gamma\\max_a Q(S_{t+1},a) $$</p><h3 id="_10-2-小差异对应不同策略语义" tabindex="-1">10.2 小差异对应不同策略语义 <a class="header-anchor" href="#_10-2-小差异对应不同策略语义" aria-label="Permalink to &quot;10.2 小差异对应不同策略语义&quot;">​</a></h3><p>Sarsa 的下一动作来自行为策略，学习 (q_\\pi) 并随策略改进；Q-learning 的最大值对应贪心目标策略，行为策略主要负责探索。这就是同策略与异策略的根本区别。</p><h3 id="_10-3-不能只凭-保守-和-激进-选算法" tabindex="-1">10.3 不能只凭“保守”和“激进”选算法 <a class="header-anchor" href="#_10-3-不能只凭-保守-和-激进-选算法" aria-label="Permalink to &quot;10.3 不能只凭“保守”和“激进”选算法&quot;">​</a></h3><p>悬崖行走让 Sarsa 看起来谨慎、Q-learning 看起来大胆，但这些标签不是算法定义。选择方法应考虑能否分离行为与目标策略、数据复用需求、函数逼近稳定性、探索机制和部署约束。</p><p><img src="'+n+'" alt="Sarsa 与 Q-learning 的目标只差一项，学习策略却不同"></p><h2 id="十一、expected-sarsa-改变了什么" tabindex="-1">十一、Expected Sarsa 改变了什么 <a class="header-anchor" href="#十一、expected-sarsa-改变了什么" aria-label="Permalink to &quot;十一、Expected Sarsa 改变了什么&quot;">​</a></h2><h3 id="_11-1-它对下一动作求策略期望" tabindex="-1">11.1 它对下一动作求策略期望 <a class="header-anchor" href="#_11-1-它对下一动作求策略期望" aria-label="Permalink to &quot;11.1 它对下一动作求策略期望&quot;">​</a></h3><p>Expected Sarsa（期望 Sarsa）不采样单个 (A_{t+1})，而是使用：</p><p>$$ R_{t+1}+\\gamma\\sum_a\\pi(a|S_{t+1})Q(S_{t+1},a) $$</p><h3 id="_11-2-它减少下一动作采样带来的方差" tabindex="-1">11.2 它减少下一动作采样带来的方差 <a class="header-anchor" href="#_11-2-它减少下一动作采样带来的方差" aria-label="Permalink to &quot;11.2 它减少下一动作采样带来的方差&quot;">​</a></h3><p>给定下一状态后，普通 Sarsa 的目标随随机选中的下一动作变化；期望 Sarsa 对当前策略的所有动作价值加权，消除这一部分随机性，但每次更新需要计算动作集合上的期望。</p><h3 id="_11-3-它仍然可以是同策略方法" tabindex="-1">11.3 它仍然可以是同策略方法 <a class="header-anchor" href="#_11-3-它仍然可以是同策略方法" aria-label="Permalink to &quot;11.3 它仍然可以是同策略方法&quot;">​</a></h3><p>若用于期望的 (\\pi) 就是生成数据的行为策略，它仍属于同策略控制。若目标策略与行为策略分离，则要重新分析其异策略语义与稳定性。</p><h2 id="十二、探索衰减怎样避免两个相反错误" tabindex="-1">十二、探索衰减怎样避免两个相反错误 <a class="header-anchor" href="#十二、探索衰减怎样避免两个相反错误" aria-label="Permalink to &quot;十二、探索衰减怎样避免两个相反错误&quot;">​</a></h2><h3 id="_12-1-衰减太快会停止学习未知动作" tabindex="-1">12.1 衰减太快会停止学习未知动作 <a class="header-anchor" href="#_12-1-衰减太快会停止学习未知动作" aria-label="Permalink to &quot;12.1 衰减太快会停止学习未知动作&quot;">​</a></h3><p>早期少量随机回报可能让某个动作暂时领先。<code>ε</code> 很快降为零后，其他动作不再被访问，错误排序难以修正。</p><h3 id="_12-2-长期固定探索会改变最终在线行为" tabindex="-1">12.2 长期固定探索会改变最终在线行为 <a class="header-anchor" href="#_12-2-长期固定探索会改变最终在线行为" aria-label="Permalink to &quot;12.2 长期固定探索会改变最终在线行为&quot;">​</a></h3><p><code>ε</code> 固定大于零时，策略永远会执行一部分随机动作。训练回报和部署行为都包含这些探索后果。若评估时关闭探索，应明确这是另一个策略，而不是把训练策略表现直接等同于评估策略。</p><h3 id="_12-3-合理目标是持续探索并在极限趋于贪心" tabindex="-1">12.3 合理目标是持续探索并在极限趋于贪心 <a class="header-anchor" href="#_12-3-合理目标是持续探索并在极限趋于贪心" aria-label="Permalink to &quot;12.3 合理目标是持续探索并在极限趋于贪心&quot;">​</a></h3><p>Greedy in the Limit with Infinite Exploration（无限探索且极限贪心）描述一种理想条件：每个状态动作对获得无限次访问，同时策略最终趋于贪心。有限训练只能近似这一目标，因此访问计数和覆盖诊断比一句“使用指数衰减”更重要。</p><h2 id="十三、学习率、初始化与随机性怎样影响训练" tabindex="-1">十三、学习率、初始化与随机性怎样影响训练 <a class="header-anchor" href="#十三、学习率、初始化与随机性怎样影响训练" aria-label="Permalink to &quot;十三、学习率、初始化与随机性怎样影响训练&quot;">​</a></h2><h3 id="_13-1-固定学习率会持续追踪近期经验" tabindex="-1">13.1 固定学习率会持续追踪近期经验 <a class="header-anchor" href="#_13-1-固定学习率会持续追踪近期经验" aria-label="Permalink to &quot;13.1 固定学习率会持续追踪近期经验&quot;">​</a></h3><p>固定 (\\alpha) 在非平稳策略下有实用价值，但动作价值会围绕目标波动。递减学习率更利于表格型理论收敛，却可能让后期新经验影响过小。</p><h3 id="_13-2-乐观初始化能够暂时促进探索" tabindex="-1">13.2 乐观初始化能够暂时促进探索 <a class="header-anchor" href="#_13-2-乐观初始化能够暂时促进探索" aria-label="Permalink to &quot;13.2 乐观初始化能够暂时促进探索&quot;">​</a></h3><p>若未访问动作初值较高，贪心选择也会轮流尝试它们，因为已访问动作在收到普通回报后可能下降。但乐观初始化的效果依赖奖励尺度和环境可重访性，不能替代一般探索机制。</p><h3 id="_13-3-多随机种子是最低限度要求" tabindex="-1">13.3 多随机种子是最低限度要求 <a class="header-anchor" href="#_13-3-多随机种子是最低限度要求" aria-label="Permalink to &quot;13.3 多随机种子是最低限度要求&quot;">​</a></h3><p>动作探索、环境转移和初始化都会制造随机性。单次训练路线更安全或回报更高，可能只是偶然。应汇总多随机种子的均值、离散程度、失败率和学习曲线，而非挑选最佳运行。</p><h2 id="十四、从表格-sarsa-走向函数逼近要警惕什么" tabindex="-1">十四、从表格 Sarsa 走向函数逼近要警惕什么 <a class="header-anchor" href="#十四、从表格-sarsa-走向函数逼近要警惕什么" aria-label="Permalink to &quot;十四、从表格 Sarsa 走向函数逼近要警惕什么&quot;">​</a></h2><h3 id="_14-1-离散动作价值表无法覆盖巨大状态空间" tabindex="-1">14.1 离散动作价值表无法覆盖巨大状态空间 <a class="header-anchor" href="#_14-1-离散动作价值表无法覆盖巨大状态空间" aria-label="Permalink to &quot;14.1 离散动作价值表无法覆盖巨大状态空间&quot;">​</a></h3><p>自动驾驶状态包含连续速度、横向误差、周围车辆关系和道路结构，直接枚举 (Q(s,a)) 很快失去可行性。函数逼近用共享参数从状态动作特征预测价值。</p><h3 id="_14-2-共享参数让一次更新影响许多状态" tabindex="-1">14.2 共享参数让一次更新影响许多状态 <a class="header-anchor" href="#_14-2-共享参数让一次更新影响许多状态" aria-label="Permalink to &quot;14.2 共享参数让一次更新影响许多状态&quot;">​</a></h3><p>表格中只修改一个格子，函数逼近却可能同时改变大量相似输入。泛化可以提高样本利用率，也可能产生灾难性干扰和分布外错误。</p><h3 id="_14-3-同策略并不自动消除不稳定" tabindex="-1">14.3 同策略并不自动消除不稳定 <a class="header-anchor" href="#_14-3-同策略并不自动消除不稳定" aria-label="Permalink to &quot;14.3 同策略并不自动消除不稳定&quot;">​</a></h3><p>Sarsa 避开了行为策略与目标策略完全分离的一部分问题，但自举、函数逼近、非平稳策略和相关样本仍会影响稳定性。深度网络版本需要目标尺度、优化器、归一化、回放方式和评估协议等额外设计。</p><h2 id="十五、放进自动驾驶前必须补哪些边界" tabindex="-1">十五、放进自动驾驶前必须补哪些边界 <a class="header-anchor" href="#十五、放进自动驾驶前必须补哪些边界" aria-label="Permalink to &quot;十五、放进自动驾驶前必须补哪些边界&quot;">​</a></h2><h3 id="_15-1-带探索策略不能直接控制真实车辆" tabindex="-1">15.1 带探索策略不能直接控制真实车辆 <a class="header-anchor" href="#_15-1-带探索策略不能直接控制真实车辆" aria-label="Permalink to &quot;15.1 带探索策略不能直接控制真实车辆&quot;">​</a></h3><p><code>ε</code>-贪心意味着主动选择随机动作。在真实道路上，随机转向或加速不可接受。探索应限制在仿真、离线数据或受控试验中，并由 Safety Shield（安全屏蔽器）、Control Barrier Function（控制屏障函数）和规则控制器提供独立约束。</p><h3 id="_15-2-考虑探索风险-不等于学会安全" tabindex="-1">15.2 “考虑探索风险”不等于学会安全 <a class="header-anchor" href="#_15-2-考虑探索风险-不等于学会安全" aria-label="Permalink to &quot;15.2 “考虑探索风险”不等于学会安全&quot;">​</a></h3><p>Sarsa 只会按照奖励和数据分布调整期望回报。罕见碰撞如果采样不足，或者安全惩罚被效率奖励抵消，动作价值仍可能偏好危险行为。硬约束不能只依赖期望奖励塑形。</p><h3 id="_15-3-风险指标必须与平均回报分开" tabindex="-1">15.3 风险指标必须与平均回报分开 <a class="header-anchor" href="#_15-3-风险指标必须与平均回报分开" aria-label="Permalink to &quot;15.3 风险指标必须与平均回报分开&quot;">​</a></h3><p>应单独报告碰撞率、越界率、最小安全距离、控制舒适性、约束违反率和最坏分位数表现。平均回报上升不能替代安全指标，也不能证明长尾场景覆盖充分。</p><h3 id="_15-4-训练策略与部署策略变化需要重新验证" tabindex="-1">15.4 训练策略与部署策略变化需要重新验证 <a class="header-anchor" href="#_15-4-训练策略与部署策略变化需要重新验证" aria-label="Permalink to &quot;15.4 训练策略与部署策略变化需要重新验证&quot;">​</a></h3><p>训练时含探索、部署时关闭探索，看似只是把 <code>ε</code> 设为零，实际已经改变策略分布。部署策略仍需独立回放、仿真、场景切片和闭环验证，不能沿用训练曲线作为证据。</p><h2 id="十六、一个最小实验应该怎样验证" tabindex="-1">十六、一个最小实验应该怎样验证 <a class="header-anchor" href="#十六、一个最小实验应该怎样验证" aria-label="Permalink to &quot;十六、一个最小实验应该怎样验证&quot;">​</a></h2><h3 id="_16-1-使用可复现的悬崖行走环境" tabindex="-1">16.1 使用可复现的悬崖行走环境 <a class="header-anchor" href="#_16-1-使用可复现的悬崖行走环境" aria-label="Permalink to &quot;16.1 使用可复现的悬崖行走环境&quot;">​</a></h3><p>明确网格尺寸、起点、终点、悬崖位置、普通步惩罚、跌落惩罚和跌落后的状态处理。终止与返回起点的语义必须与实现一致。</p><h3 id="_16-2-同时实现-sarsa-与-q-learning-对照" tabindex="-1">16.2 同时实现 Sarsa 与 Q-learning 对照 <a class="header-anchor" href="#_16-2-同时实现-sarsa-与-q-learning-对照" aria-label="Permalink to &quot;16.2 同时实现 Sarsa 与 Q-learning 对照&quot;">​</a></h3><p>两种方法使用相同初始化、学习率、折扣因子、探索率调度、随机种子集合和交互步数。只改变自举目标，才能把差异归因到学习策略语义。</p><h3 id="_16-3-分开记录训练表现与贪心评估" tabindex="-1">16.3 分开记录训练表现与贪心评估 <a class="header-anchor" href="#_16-3-分开记录训练表现与贪心评估" aria-label="Permalink to &quot;16.3 分开记录训练表现与贪心评估&quot;">​</a></h3><p>训练阶段保留探索，记录每回合回报、跌落次数和步数；评估阶段冻结 (Q) 并关闭探索，记录贪心路径与安全指标。两组结果回答不同问题，不能混成一条曲线。</p><h3 id="_16-4-检查状态动作覆盖和公式手算" tabindex="-1">16.4 检查状态动作覆盖和公式手算 <a class="header-anchor" href="#_16-4-检查状态动作覆盖和公式手算" aria-label="Permalink to &quot;16.4 检查状态动作覆盖和公式手算&quot;">​</a></h3><p>输出关键区域各动作访问次数，确认探索没有遗漏重要动作。再构造一个短五元组，手算 Sarsa 目标、误差和更新值，验证代码确实复用了目标中的 (A_{t+1})。</p><h2 id="十七、实现时最常见的错误" tabindex="-1">十七、实现时最常见的错误 <a class="header-anchor" href="#十七、实现时最常见的错误" aria-label="Permalink to &quot;十七、实现时最常见的错误&quot;">​</a></h2><h3 id="_17-1-下一动作被重复采样" tabindex="-1">17.1 下一动作被重复采样 <a class="header-anchor" href="#_17-1-下一动作被重复采样" aria-label="Permalink to &quot;17.1 下一动作被重复采样&quot;">​</a></h3><p>目标计算采样一次 (A_{t+1})，进入下一循环又采样一次，会让更新目标与实际行为不一致。正确做法是把已经选出的动作传入下一步。</p><h3 id="_17-2-在目标里误用最大动作价值" tabindex="-1">17.2 在目标里误用最大动作价值 <a class="header-anchor" href="#_17-2-在目标里误用最大动作价值" aria-label="Permalink to &quot;17.2 在目标里误用最大动作价值&quot;">​</a></h3><p>把 (Q(S_{t+1},A_{t+1})) 写成 (\\max_a Q(S_{t+1},a))，实现就变成了 Q-learning 的目标，不再是 Sarsa。</p><h3 id="_17-3-终止状态仍然选择动作" tabindex="-1">17.3 终止状态仍然选择动作 <a class="header-anchor" href="#_17-3-终止状态仍然选择动作" aria-label="Permalink to &quot;17.3 终止状态仍然选择动作&quot;">​</a></h3><p>自然终止后继续查询动作可能访问无效状态，或把随机初值带进最后目标。终止转移的自举项应为零。</p><h3 id="_17-4-训练和评估共用探索开关" tabindex="-1">17.4 训练和评估共用探索开关 <a class="header-anchor" href="#_17-4-训练和评估共用探索开关" aria-label="Permalink to &quot;17.4 训练和评估共用探索开关&quot;">​</a></h3><p>若评估仍保持训练 <code>ε</code>，随机动作会污染贪心策略性能；若训练意外关闭探索，覆盖不足又会被掩盖。两种运行模式应显式分离。</p><h3 id="_17-5-只比较最终路线长度" tabindex="-1">17.5 只比较最终路线长度 <a class="header-anchor" href="#_17-5-只比较最终路线长度" aria-label="Permalink to &quot;17.5 只比较最终路线长度&quot;">​</a></h3><p>悬崖任务的关键不只是路线，还包括训练期间跌落次数、累计回报、收敛速度和评估策略。只展示一条最终路径会隐藏在线学习代价。</p><h2 id="十八、接下来进入-q-learning" tabindex="-1">十八、接下来进入 Q-learning <a class="header-anchor" href="#十八、接下来进入-q-learning" aria-label="Permalink to &quot;十八、接下来进入 Q-learning&quot;">​</a></h2><p>Sarsa 用实际下一动作构造目标，因此把当前行为策略的探索后果纳入价值。下一个问题是：能否让行为策略继续探索，却让价值函数直接学习贪心目标策略？</p><p>下一篇将进入 Q-learning，解释为什么 (\\max_a Q(S_{t+1},a)) 让它成为异策略方法，怎样区分行为策略和目标策略，以及最大化操作为何会带来过估计偏差，并为后续 Deep Q-Network（深度 Q 网络）建立公式基础。</p><h2 id="十九、参考资料" tabindex="-1">十九、参考资料 <a class="header-anchor" href="#十九、参考资料" aria-label="Permalink to &quot;十九、参考资料&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter3/chapter3.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第 3 章表格型方法源码</a></p><p><a href="https://web.stanford.edu/class/psych209/Readings/SuttonBartoIPRLBook2ndEd.pdf" target="_blank" rel="noreferrer">Sutton 与 Barto《Reinforcement Learning: An Introduction（强化学习导论）》第 2 版全文</a></p><p><a href="https://mitpress.mit.edu/9780262039246/reinforcement-learning/" target="_blank" rel="noreferrer">MIT Press（麻省理工学院出版社）《Reinforcement Learning: An Introduction（强化学习导论）》第 2 版页面</a></p><p><a href="https://www.youtube.com/watch?v=0g4j2k_Ggc4" target="_blank" rel="noreferrer">Google DeepMind（谷歌深度思维）David Silver 强化学习课程第 5 讲</a></p><p>本文为强化学习入门系列第 07 篇。文中公式、示意图与自动驾驶案例均按教学目的重新组织，不构成真实车辆部署或安全论证。</p>',170)])])}const f=e(d,[["render",c]]);export{S as __pageData,f as default};
